package fleetgen

import (
	"bytes"
	"fmt"
	"sort"
	"strings"
	"time"
)

// renderMarkdown writes CONTENT.md: what each generated file holds, so a
// reviewer can read the policies without opening YAML.
func (c *Content) renderMarkdown() []byte {
	var b bytes.Buffer
	w := func(format string, a ...any) { fmt.Fprintf(&b, format, a...) }
	w("# spoor Fleet content (generated)\n\n")
	w("Generated by `internal/fleetgen` from `internal/state` (tables, ATC, policy guard) and catalog %s. "+
		"Do not edit; regenerate with `go test ./internal/fleetgen -run TestGolden -update`.\n\n", c.CatalogVersion)
	w("Heartbeat windows: the sensor policy and the \"spoor sensor unhealthy\" label accept a heartbeat up to %s old; "+
		"every other spoor policy embeds a guard of %s, so it fails closed when the sensor stops or its database "+
		"is deleted, but not each time a laptop sleeps. Detection and bypass policies look back %s.\n\n",
		human(c.AlertWindow), human(c.GuardWindow), human(DetectionLookback))

	w("## State database paths\n\n| OS | state database | binary |\n|---|---|---|\n")
	for _, p := range Platforms {
		w("| %s | `%s` | `%s` |\n", p, c.DBPaths[p], c.BinPaths[p])
	}
	w("\n")

	w("## Files\n\n| file | content |\n|---|---|\n")
	w("| `%s` | ATC fragment to merge into agent options (all %d spoor tables, one block per OS) |\n", FileATC, len(c.ATC[PlatformLinux]))
	w("| `%s` | the fragment merged into a typical base configuration |\n", FileATCExample)
	for _, p := range c.Profiles {
		w("| `%s/` | %s: %s, %s, %s |\n", p.Name, p.Title, plural(len(p.Labels), "label"),
			plural(len(p.Policies), "policy"), plural(len(p.Reports), "report"))
	}
	w("| `%s` | opt-in exec-event reports (privacy warning inside) |\n\n", FileOptIn)

	tables := make([]string, 0, len(c.ATC[PlatformLinux]))
	for t := range c.ATC[PlatformLinux] {
		tables = append(tables, t)
	}
	sort.Strings(tables)
	w("Tables: %s.\n\n", "`"+strings.Join(tables, "`, `")+"`")

	for _, p := range c.Profiles {
		w("## Profile `%s`: %s\n\n%s\n\n", p.Name, p.Title, p.Summary)
		w("### Labels\n\n")
		for _, l := range p.Labels {
			w("- **%s**: %s\n", l.Name, l.Description)
		}
		w("\n### Policies\n\n| policy | heartbeat window | checks |\n|---|---|---|\n")
		for _, pol := range p.Policies {
			win := "none (live table)"
			if pol.Window > 0 {
				win = human(pol.Window)
			}
			w("| %s | %s | %s |\n", pol.Name, win, mdCell(pol.Description))
		}
		w("\n### Reports\n\n| report | interval | logging | to log destination |\n|---|---|---|---|\n")
		for _, r := range p.Reports {
			w("| %s | %s | %s | %v |\n", r.Name, human(secs(r.Interval)), r.Logging, r.AutomationsEnabled)
		}
		w("\n")
	}
	w("## Opt-in exec-event reports\n\n```\n%s\n```\n\n", OptInWarning)
	for _, r := range c.OptIn {
		w("- **%s** (`%s`, every %s): %s\n", r.Name, r.Platform, human(secs(r.Interval)), r.Description)
	}
	return b.Bytes()
}

func mdCell(s string) string { return strings.ReplaceAll(s, "|", "\\|") }

func secs(n int) time.Duration { return time.Duration(n) * time.Second }

func plural(n int, noun string) string {
	if n == 1 {
		return "1 " + noun
	}
	if strings.HasSuffix(noun, "y") {
		return fmt.Sprintf("%d %sies", n, strings.TrimSuffix(noun, "y"))
	}
	return fmt.Sprintf("%d %ss", n, noun)
}
